    "justification": "Material is primary patient-derived blood cells, not in vitro cell lines or model systems."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "RNA extracted from 110 patients with CAD (CADi>23) and from 112 partially matched controls without CAD (CADi=0); study described as parallel group design.",
    "justification": "Clear case (CAD) versus control (no CAD) group comparison."
